// What `eas metadata:push` reads (eas.json → submit.production.ios.metadataPath).
//
// The listing itself is store.config.json, generated by `npm run store:build`. This only adds
// the App Review contact — a name, an email and a phone number are personal data and stay out
// of the repository, so they come from the environment of whoever pushes. See docs/STORE.md.
const config = require('./store.config.json');

const CONTACT = {
  firstName: 'APP_REVIEW_FIRST_NAME',
  lastName: 'APP_REVIEW_LAST_NAME',
  email: 'APP_REVIEW_EMAIL',
  phone: 'APP_REVIEW_PHONE',
};

module.exports = () => {
  const missing = Object.values(CONTACT).filter((name) => !process.env[name]);
  if (missing.length > 0) {
    throw new Error(`Set ${missing.join(', ')}: the App Review contact (docs/STORE.md).`);
  }

  const contact = Object.fromEntries(
    Object.entries(CONTACT).map(([field, name]) => [field, process.env[name]]),
  );
  return { ...config, apple: { ...config.apple, review: { ...contact, ...config.apple.review } } };
};
